# ---------------------------------------------------------------------------
# Scale constructor error contracts
# ---------------------------------------------------------------------------


def test_linear_scale_rejects_nan_in_domain():
    """LinearScale must reject NaN in domain with ValueError."""
    with pytest.raises(ValueError, match="finite"):
        fr.LinearScale(domain=[float("nan"), 10.0], range=[0.0, 1.0])


def test_linear_scale_rejects_infinity_in_domain():
    """LinearScale must reject infinity in domain."""
    with pytest.raises(ValueError, match="finite"):
        fr.LinearScale(domain=[0.0, float("inf")], range=[0.0, 1.0])


def test_log_scale_rejects_base_zero():
    """LogScale must reject base=0."""
    with pytest.raises(ValueError, match="base must be"):
        fr.LogScale(domain=[1.0, 100.0], range=[0.0, 2.0], base=0.0)


def test_quantile_scale_rejects_nan_in_domain():
    """QuantileScale must reject NaN in domain sample."""
    with pytest.raises(ValueError, match="finite"):
        fr.QuantileScale(domain=[1.0, float("nan"), 3.0], range=[0.0, 1.0])


def test_threshold_scale_rejects_nan_in_thresholds():
    """ThresholdScale must reject NaN in thresholds."""
    with pytest.raises(ValueError, match="finite"):
        fr.ThresholdScale(domain=[float("nan")], range=[1.0, 2.0])


# ---------------------------------------------------------------------------
# Extreme values on scales
# ---------------------------------------------------------------------------


def test_linear_infinity_input_returns_nan():
    """LinearScale.scale(inf) should return NaN (out of domain)."""
    s = fr.LinearScale(domain=[0.0, 10.0], range=[0.0, 1.0])
    assert math.isnan(s.scale(float("inf")))
    assert math.isnan(s.scale(float("-inf")))


def test_log_scale_very_small_positive_domain():
    """LogScale with domain near subnormal (1e-300) should not overflow."""
    s = fr.LogScale(domain=[1e-300, 1.0], range=[0.0, 300.0])
    assert math.isclose(s.scale(1e-300), 0.0, abs_tol=1e-6)
    assert math.isclose(s.scale(1.0), 300.0, abs_tol=1e-6)


def test_very_large_float_chart_renders():
    """Chart with 1e300-scale values should not crash."""
    df = pl.DataFrame({"x": [1e300, 2e300, 3e300], "y": [1.0, 2.0, 3.0]})
    svg = fr.Chart(df).mark_point().encode(x="x", y="y").show_svg()
    assert "<svg" in svg
    assert "NaN" not in svg


# ---------------------------------------------------------------------------
# Spec round-trips
# ---------------------------------------------------------------------------


def test_chartspec_round_trip():
    """ChartSpec survives JSON round-trip with mark and encoding fields intact."""
    cs = ChartSpec(mark="point", x="xcol", y="ycol")
    rt = ChartSpec.from_json(cs.to_json())
    assert rt == cs


def test_aggregate_spec_round_trip():
    """Aggregate transform spec survives JSON round-trip."""
    spec = Aggregate(
        ops=[AggregateOp("price", "mean", "avg_price")],
        groupby=["region"],
    )
    cs = ChartSpec(mark="bar", x="region", transforms=[spec])
    rt = ChartSpec.from_json(cs.to_json())
    assert rt == cs


