def test_boolean_column_as_x():
    """Boolean column as x should render (treated as ordinal)."""
    df = pl.DataFrame({"x": [True, False, True, False], "y": [1.0, 2.0, 3.0, 4.0]})
    svg = fr.Chart(df).mark_point().encode(x="x", y="y").show_svg()
    assert "<svg" in svg


